anti rotoli ti servono?','roll'=>'rotolo','rolls'=>'rotoli','/&nbsp;roll'=>'/&nbsp;rotolo','Square meters / panels'=>'Metri quadrati / pannelli','How many panels do you need?'=>'Quanti pannelli ti servono?','panel'=>'pannello','panels'=>'pannelli','/&nbsp;panel'=>'/&nbsp;pannello','Calculate panels needed'=>'Calcola i pannelli necessari','Meters / pieces'=>'Metri / pezzi','How many meters do you need?'=>'Quanti metri ti servono?','How many pieces do you need?'=>'Quanti pezzi ti servono?','piece'=>'pezzo','pieces'=>'pezzi','/&nbsp;piece'=>'/&nbsp;pezzo','Meters'=>'Metri','meter'=>'metro','meters'=>'metri','/&nbsp;meter'=>'/&nbsp;metro','Coverage / container'=>'Resa / contenitore','Area to be glued?'=>'Superficie da incollare?','How many containers do you need?'=>'Quanti contenitori ti servono?','container'=>'contenitore','containers'=>'contenitori','kg'=>'kg','/&nbsp;container'=>'/&nbsp;contenitore','Weight'=>'Peso','Calculate area from room dimensions'=>'Calcola la superficie dalle dimensioni del locale','Pieces (default)'=>'Pezzi (predefinito)']];